code='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            bounds = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in bounds:
                    bounds[color] = [y, y, x, x]
                else:
                    b = bounds[color]
                    b[0], b[1] = min(b[0], y), max(b[1], y)
                    b[2], b[3] = min(b[2], x), max(b[3], x)
            layers = sorted(bounds, key=lambda color: (bounds[color][1] - bounds[color][0] + 1) * (bounds[color][3] - bounds[color][2] + 1), reverse=True)
            remap = {color: layers[-1 - i] for i, color in enumerate(layers)}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
'''
